		inline bool Read(const FJson& Json, AcceptRequest& Out, std::string& Error)
		{
			if (!Json.IsObject())
			{
				Error = "expected an object";
				return false;
			}
			AcceptRequest Result;
			if (const FJson* Value = Json.Find("type"))
			{
				if (!Read(*Value, Result.Type, Error))
				{
					Error = "type: " + Error;
					return false;
				}
			}
			if (const FJson* Value = Json.Find("version"))
			{
				if (!Read(*Value, Result.Version, Error))
				{
					Error = "version: " + Error;
					return false;
				}
			}
			Out = std::move(Result);
			return true;
		}

		inline FJson Write(const AcceptRequest& Value)
		{
			FJson Json = FJson::MakeObject();
			if (Value.Type)
			{
				Json.Set("type", Write(*Value.Type));
			}
			if (Value.Version)
			{
				Json.Set("version", Write(*Value.Version));
			}
			return Json;
		}

